using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using DoomSNESed;
namespace DoomSNESed { public static class MusicRefinementTests {
 [DllImport("DoomSNESAudio.dll",CallingConvention=CallingConvention.Cdecl)]static extern int DoomAudioScan(byte[] d,byte[] r,int song,int origin,int frames,[Out]int[] records,int capacity);
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 public static void Run(string path,string output){checks=0;output=Path.Combine(output,"music-refinement-09")+Path.DirectorySeparatorChar;Directory.CreateDirectory(output);var rom=new Rom(path,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"));byte[] b=rom.Bytes;
 var input=new ImportedMusic{Name="SPC timing fixture",Report="",Seconds=61};foreach(double t in new[]{0.0,1,2,10,30,60})input.Notes.Add(new MusicNote{Start=t,End=t+.1,Key=60,Velocity=100,Channel=0,Program=30});var set=new MusicSettings();set.Assignments.Add(new MusicAssignment{Channel=0,Program=30,Patch=44});var music=MusicImport.Convert(input,"E1M1",1,0,false,set);AudioBuild.ValidateMusic(music);int[] trace=new int[200000*8];int n=DoomAudioScan(NativeMusicGate.Driver(b),MusicBank.PreviewRam(b,music),set.Song,set.Origin,32000*62,trace,200000);var onset=Enumerable.Range(0,n).Where(i=>trace[i*8+1]==0x18b0&&trace[i*8+3]!=1).Select(i=>trace[i*8]/1024000.0).ToArray();Check(onset.Length==6,"six exact native note attacks");for(int i=0;i<onset.Length;i++){double error=onset[i]-input.Notes[i].Start;Console.WriteLine("onset "+onset[i]+" error "+error);Check(Math.Abs(error)<.065,"absolute timing at "+input.Notes[i].Start+" seconds");}
 foreach(var patch in MusicLibrary.All(b)){var single=new ImportedMusic{Name="Sample "+patch.Id,Report="",Seconds=1};single.Notes.Add(new MusicNote{Start=0,End=.75,Key=60,Velocity=100});var settings=new MusicSettings{NaturalRelease=false};settings.Assignments.Add(new MusicAssignment{Patch=patch.Id});MusicLibrary.Prepare(b,settings);var song=MusicImport.Convert(single,"E1M1",1,0,false,settings);AudioBuild.ValidateMusic(song);var ram=MusicBank.PreviewRam(b,song);int pointer=Bin.U16(ram,Bin.U16(ram,0x1ee2)+patch.Id*2);Check(pointer>=0x6517&&pointer+6<=settings.Origin,"sample "+patch.Id+" free assignment and relocated BSN");int rate;var pcm=NativeAudio.Render(b,ram,0,settings.Song,1,out rate);int packedRate=rate;var resident=MusicBank.All(b).First(k=>k.Instruments.Any(i=>i.Id==patch.Id));var baseline=new MusicSettings{NaturalRelease=false,Bank=resident.Module,Origin=resident.Origin,Song=resident.Song};baseline.Assignments.Add(new MusicAssignment{Patch=patch.Id});var baselineSong=MusicImport.Convert(single,"E1M1",1,0,false,baseline);var reference=NativeAudio.Render(b,MusicBank.PreviewRam(b,baselineSong),0,baseline.Song,1,out rate);Check(packedRate==rate,"sample "+patch.Id+" retains original DSP pitch");NativeAudio.Render(b,ram,4,settings.Song,1.5,out rate);Check(rate==0,"sample "+patch.Id+" tight mode releases after MIDI note-off");Check(pcm.Any(v=>v!=0)==reference.Any(v=>v!=0),"sample "+patch.Id+" audibility matches original bank");}
 var pressure=new ImportedMusic{Name="Priority",Report="",Seconds=3};pressure.Notes.Add(new MusicNote{Start=0,End=2.5,Program=30,Key=60,Velocity=90});for(int i=0;i<50;i++)pressure.Notes.Add(new MusicNote{Start=.02+i*.04,End=.1+i*.04,Program=90,Channel=1,Key=65,Velocity=60});set.Assignments[0].Priority=5;var protectedSong=MusicImport.Convert(pressure,"E1M1",1,0,false,set);var empty=new ImportedMusic{Name="Lead only",Report="",Seconds=3};empty.Notes.Add(pressure.Notes[0]);Check(protectedSong.Sequence.SequenceEqual(MusicImport.Convert(empty,"E1M1",1,0,false,set).Sequence),"priority preserves entire lead duration under dense quiet pad attacks");
 foreach(int id in rom.WallTextures.Where(id=>id>=4&&GraphicsAssets.Describe(b,false,id).Width==128&&GraphicsAssets.Describe(b,false,id).Height==128).Take(1)){var test=new Rom(path,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"));test.Project.RetailAssets=true;var asset=GraphicsAssets.Describe(b,false,id);var pixels=GraphicsAssets.Decode(b,asset);test.Project.Graphics.Add(new GraphicReplacement{Id=id,Width=128,Height=128,Pixels=pixels});byte[] result=test.Compile();Check(GraphicsAssets.Decode(result,GraphicsAssets.Describe(result,false,id)).SequenceEqual(pixels),"128x128 wall "+id+" replacement round trip");for(int x=0;x<128;x++)Check(GraphicsAssets.Address(result,asset.Header+2+x*3)<0x200000,"wall bank reachable by Super FX "+id+"/"+x);if(id==rom.WallTextures.First(k=>k>=4&&GraphicsAssets.Describe(b,false,k).Width==128&&GraphicsAssets.Describe(b,false,k).Height==128)){File.WriteAllBytes(output+"door.sfc",result);test.SavePatch(output+"door.dse",result);}}
 var mixed=new MusicSettings();mixed.Assignments.Add(new MusicAssignment{Patch=52});mixed.Assignments.Add(new MusicAssignment{Channel=1,Patch=45});MusicLibrary.Prepare(b,mixed);var score=new ImportedMusic{Name="Mixed bank",Report="",Seconds=2};score.Notes.Add(new MusicNote{Key=60,Start=0,End=1.5,Velocity=100});score.Notes.Add(new MusicNote{Key=40,Channel=1,Start=0,End=1.5,Velocity=100});var songMix=MusicImport.Convert(score,"E1M1",2,0,false,mixed);rom.Project.RetailAssets=true;rom.Project.Audio.Music.Add(songMix);byte[] mixRom=rom.Compile();File.WriteAllBytes(output+"mixed.sfc",mixRom);rom.SavePatch(output+"mixed.dse",mixRom);int module=Bin.U16(mixRom,AudioRom.SongTable)>>8;Check(AudioRom.Module(mixRom,module).SequenceEqual(MusicBank.PreviewRam(b,songMix)),"mixed sample bank ROM upload matches native preview exactly");
 File.WriteAllText(Path.Combine(output,"results.txt"),"PASS "+checks+" checks: native timing through 60 seconds, every patch retains DSP pitch and releases, voice priority, 128x128 texture banks, mixed sample upload.\r\n");}
}
}